mapper.select:
SELECT EXISTS (
  SELECT 1 FROM workflow_instances WHERE source_event_id = #{sourceEventId, jdbcType=OTHER}
)

mapper.update:
UPDATE workflow_instances
SET status = #{status}, current_task = #{currentTask}, version = version + 1
WHERE id = #{id, jdbcType=OTHER}
  AND tenant_id = #{tenantId}
  AND version = #{version}
